Creating a complete auth system with Node.js + Express, bcryptjs, JWT, and SQLite.
<function_calls>
[
  {
    "type": "write",
    "path": "/tmp/package.json",
    "file_content": "{
  "name": "auth-app",
  "version": "1.0.0",
  "main": "server.js",
  "scripts": {
    "start": "node server.js",
    "test": "curl tests"
  },
  "dependencies": {
    "express": "^4.18.2",
    "better-sqlite3": "^9.0.0",
    "bcryptjs": "^2.4.3",
    "jsonwebtoken": "^9.1.0",
    "express-rate-limit": "^7.1.0"
  }
}
"
  },
  {
    "type": "write",
    "path": "/tmp/server.js",
    "file_content": "const express = require('express');
const Database = require('better-sqlite3');
const bcrypt = require('bcryptjs');
const jwt = require('jsonwebtoken');
const rateLimit = require('express-rate-limit');

const app = express();
const db = new Database('auth.db');
const JWT_SECRET = process.env.JWT_SECRET || 'dev-secret-key-change-in-production';

// Initialize database
db.exec(`
  CREATE TABLE IF NOT EXISTS users (
    id INTEGER PRIMARY KEY,
    email TEXT UNIQUE NOT NULL,
    password_hash TEXT NOT NULL,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  )
`);

// Rate limiter: 5 attempts per 15 minutes per email
const loginLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  keyGenerator: (req) => req.body.email || req.ip,
  handler: (req, res) => {
    res.status(429).json({ error: 'Too many login attempts. Try again in 15 minutes.' });
  },
  skip: (req) => !req.body.email
});

app.use(express.json());

// Signup
app.post('/signup', (req, res) => {
  const { email, password } = req.body;

  if (!email || typeof email !== 'string' || !email.includes('@')) {
    return res.status(400).json({ error: 'Valid email required' });
  }

  if (!password || password.length < 8) {
    return res.status(400).json({ error: 'Password must be at least 8 characters' });
  }

  try {
    const hash = bcrypt.hashSync(password, 10);
    const stmt = db.prepare('INSERT INTO users (email, password_hash) VALUES (?, ?)');
    stmt.run(email.toLowerCase(), hash);

    res.status(201).json({ message: 'User created successfully' });
  } catch (err) {
    if (err.message.includes('UNIQUE constraint failed')) {
      return res.status(409).json({ error: 'Email already registered' });
    }
    console.error(err);
    res.status(500).json({ error: 'Signup failed' });
  }
});

// Login
app.post('/login', loginLimiter, (req, res) => {
  const { email, password } = req.body;

  if (!email || !password) {
    return res.status(400).json({ error: 'Email and password required' });
  }

  const user = db.prepare('SELECT * FROM users WHERE email = ?').get(email.toLowerCase());

  if (!user) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  if (!bcrypt.compareSync(password, user.password_hash)) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  const token = jwt.sign(
    { id: user.id, email: user.email },
    JWT_SECRET,
    { expiresIn: '7d' }
  );

  res.json({ token, expiresIn: '7d' });
});

// Protected route middleware
const authRequired = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'No token provided' });
  }

  try {
    const decoded = jwt.verify(token, JWT_SECRET);
    req.user = decoded;
    next();
  } catch (err) {
    res.status(401).json({ error: 'Invalid or expired token' });
  }
};

// Protected route example
app.get('/profile', authRequired, (req, res) => {
  res.json({ message: 'Protected data', user: req.user });
});

app.listen(3000, () => {
  console.log('Auth server running on http://localhost:3000');
  console.log('\nEndpoints:');
  console.log('  POST /signup    - { email, password }');
  console.log('  POST /login     - { email, password }');
  console.log('  GET /profile    - Requires Authorization: Bearer <token>');
});
"
  },
  {
    "type": "write",
    "path": "/tmp/curl-tests.sh",
    "file_content": "#!/bin/bash

# Signup
echo "=== Signup ==="
SIGNUP=$(curl -s -X POST http://localhost:3000/signup \
  -H "Content-Type: application/json" \
  -d '{"email":"user@example.com","password":"securepass123"}')
echo $SIGNUP

# Login
echo "\n=== Login ==="
LOGIN=$(curl -s -X POST http://localhost:3000/login \
  -H "Content-Type: application/json" \
  -d '{"email":"user@example.com","password":"securepass123"}')
echo $LOGIN

# Extract token
TOKEN=$(echo $LOGIN | grep -o '"token":"[^"]*' | cut -d'"' -f4)

# Access protected route
echo "\n=== Protected Route ==="
curl -s -X GET http://localhost:3000/profile \
  -H "Authorization: Bearer $TOKEN" | jq .

# Rate limiting test
echo "\n=== Rate Limiting Test (5 attempts max) ==="
for i in {1..7}; do
  echo "Attempt $i:"
  curl -s -X POST http://localhost:3000/login \
    -H "Content-Type: application/json" \
    -d '{"email":"user@example.com","password":"wrongpassword"}' | jq .
  sleep 0.5
done
"
